SELECT 
FROM employee_contract c JOIN employee e ON e.id = c.employee_id
WHERE 1 = 1
AND c.employee_id = #{employeeId}
AND c.ends_on >= CURRENT_DATE
AND c.ends_on < CURRENT_DATE

    AND c.renewal_status = 'NOT_DUE' AND c.ends_on >= #{dueFrom}
    AND c.ends_on <= #{dueThrough}


    AND c.renewal_status = #{renewalStatus}
    AND c.ends_on > #{dueThrough}


ORDER BY c.ends_on ASC, c.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM employee_contract c JOIN employee e ON e.id = c.employee_id
WHERE 1 = 1
AND c.employee_id = #{employeeId}
AND c.ends_on >= CURRENT_DATE
AND c.ends_on < CURRENT_DATE

    AND c.renewal_status = 'NOT_DUE' AND c.ends_on >= #{dueFrom}
    AND c.ends_on <= #{dueThrough}


    AND c.renewal_status = #{renewalStatus}
    AND c.ends_on > #{dueThrough}

