INSERT INTO employee_contract (
    contract_no, employee_id, contract_type, signed_on, starts_on, ends_on, renewal_status,
    source_version_id, renewed_from_contract_id, notes, version_no, created_by, updated_by
) VALUES (
    #{contractNo}, #{employeeId}, #{contractType}, #{signedOn}, #{startsOn}, #{endsOn},
    'NOT_DUE', #{sourceVersionId}, #{renewedFromContractId}, #{notes}, 0, #{createdBy}, #{createdBy}
