UPDATE employee_contract
SET renewal_status = 'RENEWED', version_no = version_no + 1, updated_by = #{operatorId}
WHERE id = #{id} AND version_no = #{versionNo} AND renewal_status = 'NOT_DUE'

UPDATE employee_contract
SET renewal_status = 'NOT_RENEWING', version_no = version_no + 1, updated_by = #{operatorId}
WHERE id = #{id} AND version_no = #{versionNo} AND renewal_status = 'NOT_DUE'
